with nq as (
  insert into public.questions (stage, question_type, stem, explanation, subject_id, topic_id, difficulty, marks, estimated_seconds, origin, historical_paper_id, status, source_year, source_page, image_url, created_by)
  values ('PE', 'mcq', 'Read the passage and answer the question.

(Excerpts from Word Power Made Easy by Norman Lewis and Why We Lie by Robin Lloyd.)

It was the famous Greek philosopher and cynic Diogenes who went around the streets of Athens, lantern in hand, looking for an honest person.

This was over two thousand years ago, but I would presume that Diogenes would have as little success in his search today. Lying seems to be an integral weakness of mortal character – I doubt that few human beings would be so brash as to claim that they have never in their lives told at least a partial untruth. Indeed, one philologist goes so far as to theorize that language must have been invented for the sole purpose of deception. Perhaps so. It is certainly true that animals seem somewhat more honest than humans, maybe because they are less gifted mentally. Why do people lie? To increase their sense of importance, to escape punishment, to gain an end that would otherwise be denied them, out of long standing habit, or sometimes because they actually do not know the difference between facts and fancy. These are the common reasons for falsification.

We all lie, all the time. It causes problems, to say the least. So why do we do it? "It''s tied in with self-esteem," says University of Massachusetts psychologist Robert Feldman. "We find that as soon as people feel that their self-esteem is threatened, they immediately begin to lie at higher levels."

Not all lies are harmful. In fact, sometimes lying is the best approach for protecting privacy and ourselves and others from malice, some researchers say. Some deception, such as boasting and lies in the name of tact and politeness, can be classified as less than serious. But bald-faced lies (whether they involve leaving out the truth or putting in something false), are harmful, as they corrode trust and intimacy—the glue of society.

"We''re trying not so much to impress other people but to maintain a view of ourselves that is consistent with the way they would like us to be," Feldman said. We want to be agreeable, to make the social situation smoother or easier, and to avoid insulting others through disagreement or discord. Men lie no more than women, but they tend to lie to make themselves look better, while women are more likely to lie to make the other person feel better.

People should become more aware of the extent to which we tend to lie and that honesty yields more genuine relationships and trust. "The default ought to be to be honest and accurate ... We''re better off if honesty is the norm. It''s like the old saying: honesty is the best policy."

Question: The authors are mainly concerned with', 'The passage explains why people lie (self-esteem, escaping punishment, habit, tact) and says “We all lie, all the time”: lying is presented as part of everyday life.',
    (select id from public.subjects where slug = 'english-communication'),
    (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'english-communication' and t.slug = 'comprehension'),
    'standard', 1, 90, 'historical_official', (select h.id from public.historical_papers h join public.source_documents d on d.id = h.source_document_id where h.exam_year = 2010 and h.stage = 'PE' and d.document_type = 'past_paper' limit 1), 'awaiting_review', 2010, 2, null, '324cdca7-eed3-47a2-876f-587d20a478dd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct, position)
  select nq.id, v.label, v.body, v.ok, v.pos from nq, (values ('A', 'how mortals are determined to avoid telling untruths', false, 1), ('B', 'describing the different ways people react to deception', false, 2), ('C', 'why animals are less gifted than humans', false, 3), ('D', 'describing why telling untruths is a way of life', true, 4)) as v(label, body, ok, pos)
  returning 1
), r as (
  insert into public.question_references (question_id, source_document_id, citation)
  select nq.id, (select source_document_id from public.historical_papers where id = (select h.id from public.historical_papers h join public.source_documents d on d.id = h.source_document_id where h.exam_year = 2010 and h.stage = 'PE' and d.document_type = 'past_paper' limit 1)), 'BCSE 2010 Preliminary Examination (RCSC), question 1, page 2' from nq
  returning 1
)
insert into public.content_reviews (entity_type, entity_id, reviewer_id, action, to_status, comment)
select 'question', nq.id, '324cdca7-eed3-47a2-876f-587d20a478dd', 'comment', 'awaiting_review',
  'Past paper 2010 Q1. Answer confidence: high.' from nq;

