  select nq.id, v.label, v.body, v.ok, v.pos from nq, (values ('A', 'creating trust', false, 1), ('B', 'attracting the opposite sex', false, 2), ('C', 'allowing others to look better', false, 3), ('D', 'making themselves look better or superior', true, 4)) as v(label, body, ok, pos)
  returning 1
