  values ('PE', 'mcq', 'Bumthang is in central Bhutan. Some Bumthaps (people of Bumthang) speak Sharchop and some speak Khengkha. If 70% of Bumthaps speak Sharchop and 60% speak Khengkha, what is the minimum percentage of Bumthaps who speak both?', '70% + 60% = 130%. Since the total cannot exceed 100%, at least 130 − 100 = 30% must speak both.',
    (select id from public.subjects where slug = 'logic-analytical-problem-solving'),
    (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.slug = 'logic-analytical-problem-solving' and t.slug = 'sets-and-percentages'),
