  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct, position)
  select nq.id, v.label, v.body, v.ok, v.pos from nq, (values ('A', '30%', true, 1), ('B', '25%', false, 2), ('C', '20%', false, 3), ('D', '15%', false, 4)) as v(label, body, ok, pos)
